import re
import unicodedata

try:
    from . import tm_album_artist_deps as compilations
except ImportError:  # run outside Picard (tests)
    import tm_album_artist_deps as compilations

# choose(): MusicBrainz could not be asked for a band's members - the album artist the files
# already hold stays (a re-run during an outage neither renames nor moves a settled album)
UNKNOWN = ("",)
# a database not asked at all (Discogs off, no token): no answer - never "no members" (NAM-8)
NOT_ASKED = ()

# the most words after the member's name ("and His Orchestra", "& The Silver Bullet Band",
# "and The Baron Von Bielski Orchestra")
MAX_TAIL_WORDS = 6


def settings(profile) -> dict:
    c = profile.get("album_artist") if hasattr(profile, "get") else None
    return c if isinstance(c, dict) else {}


def enabled(profile) -> bool:
    return bool(settings(profile).get("lead"))


def fold(s) -> str:
    """A name compared without case, accents, punctuation or "&"/"and" differences."""
    s = str(s or "").replace("ø", "o").replace("Ø", "O").replace("æ", "ae").replace("Æ", "AE")
    s = unicodedata.normalize("NFKD", s).encode("ascii", "ignore").decode().casefold()
    s = s.replace("&", " and ").replace("’", "'")
    return " ".join(re.sub(r"[^a-z0-9' ]+", " ", s).split())


def _no_the(s: str) -> str:
    return s[4:] if s.startswith("the ") else s


def leader_of(band: str, members) -> tuple | None:
    """The member (name, sort name, MusicBrainz ID) a band is named after: the band's name is
    that member's whole name followed by up to MAX_TAIL_WORDS words ("Pat Metheny Group"); of
    several, the longest name. None when no member's name starts it."""
    b = _no_the(fold(band))
    best = None
    for m in members or ():
        name = fold(m[0])
        if not name or not b.startswith(name + " "):
            continue
        if len(b[len(name):].split()) > MAX_TAIL_WORDS:
            continue
        # NAM-8: a duo or trio named after its equal members ("Jimmy Page & Robert Plant",
        # MusicBrainz's group of the two): the rest of the name is the other members' names alone
        rest = [x for x in re.split(r"\s*(?:\band\b|,)\s*", b[len(name):]) if x.strip()]
        others = {_no_the(fold(o[0])) for o in members if fold(o[0]) != name}
        if rest and all(_no_the(x.strip()) in others for x in rest):
            continue
        if best is None or len(name) > len(fold(best[0])):
            best = m
    return best


def _first(t, key) -> str:
    v = t.get(key)
    v = v if isinstance(v, list) else [v] if v else []
    return str(v[0]) if v else ""


def _list(t, key) -> list:
    v = t.get(key)
    return [str(x) for x in (v if isinstance(v, list) else [v] if v else [])]


def choose(t: dict, profile, members_of=None, discogs_members_of=None, find_ids=None, album=None):
    """(name, sort name, MusicBrainz ID, Discogs ID) of the album artist for tags t, or None to
    keep the credit. members_of(mbid) -> [(name, sort, id), ...] of a band (None: unknown);
    discogs_members_of(discogs id) -> [(name, "", "", discogs id), ...], asked when MusicBrainz
    names no leader (or the band has no MusicBrainz ID). find_ids(name, mbid) -> (mbid, discogs
    id): the band's IDs when the credit lacks them or its own lead to no leader - the Discogs
    artist its MusicBrainz entry links to, or (no ID at all: a shop's credit) the one MusicBrainz
    artist of exactly that name - so the rule holds whichever source the album was tagged from.
    ALBUM: every track's tags (NAM-8's classical test; T alone when not given)."""
    c = settings(profile)
    if not c.get("lead") or compilations.is_various(t):
        return None
    credit = _first(t, "albumartist")
    if not credit:
        return None
    mine = {fold(k): str(v).strip() for k, v in (c.get("file_under") or {}).items()
            if str(k).strip() and str(v).strip()}
    # (a credit already written one value per artist; a Discogs release gives its credit as one
    # text, and its artists separately: the engine passes those along unwritten. A comma or "&"
    # in the text alone proves nothing: "Earth, Wind & Fire")
    values = _list(t, "albumartist")
    split = len(values) >= 2
    names = _list(t, "albumartists") or _list(t, "~discogs_albumartists") or (values if split else [])
    ids = _list(t, "musicbrainz_albumartistid")

    def changed(name):
        """NAME is not already the whole album artist."""
        return split or fold(name) != fold(credit)

    # (the Discogs ID: a Partial album's tag, or the credited Discogs artists the engine passes
    # along unwritten for a release tagged from Discogs)
    sorts = _list(t, "~albumartists_sort")
    dg = _list(t, "discogs_albumartist_id") or _list(t, "~discogs_albumartist_id")

    def mapped(name):
        """Your own name for NAME: (name, keep) - keep when you mapped it to itself."""
        if fold(name) in mine:
            to = mine[fold(name)]
            return to, fold(to) == fold(name)
        return None, False

    to, keep = mapped(credit) if not split else (None, False)    # (of a split credit: its lead, below)
    if keep:
        return None
    if to:
        return _found(to, ids, members_of)
    if _first(t, "~classical"):
        # CLS-4: a classical album's album artist is its release's whole credit ("Johann
        # Sebastian Bach; Glenn Gould", "Beethoven, Steven Isserlis, Robert Levin") - never cut
        # to a lead (engine.Engine marks a classical album: classical.is_classical)
        return None
    # NAM-1: a band credited after its members, Discogs's "Thomas Strønen / Iain Ballamy : Food",
    # is the band ("Food"), not its first member: the " : " puts the members before the act
    band_at = -1
    if len(names) >= 2 and " : " in credit:
        after = fold(credit.rsplit(" : ", 1)[1])
        band_at = next((k for k, n in enumerate(names) if fold(n) == after), -1)
    joined = credit if not split else _first(t, "~albumartist_credit")
    if band_at < 0 and band_then_lineup(joined, names, ids, dg, members_of, discogs_members_of):
        band_at = 0                  # NAM-1b: "Bill Bruford's Earthworks - Django Bates, ...": the band
    if band_at >= 0:
        aligned = lambda xs: xs[band_at] if len(xs) == len(names) else ""   # noqa: E731
        lead = (names[band_at], aligned(sorts), aligned(ids), aligned(dg))
    elif len(names) >= 2:                               # a joint credit: its first artist ...
        # (your own name for its first artist goes first: file_under over the rules; a
        # "feat."/"with"/"presents" credit names its lead first, whatever the members say)
        # (the credit as one text: the album artist itself, or - written one value per artist -
        # the database's credit the engine passes along unwritten)
        if not mapped(names[0])[0] and guest_after_partners(joined, names):
            return None              # (partners first, a guest after: the whole credit)
        equals = None if mapped(names[0])[0] or lead_credit(joined, names) \
            else _equals(names, ids, dg, members_of, discogs_members_of,
                         persons=persons_as_equals(joined, names) and not classical(album or [t], names, ids, profile))
        if equals is True:
            return None              # ... NAM-8: unless a collaboration of equals - the whole credit
        if equals == "unknown":
            return UNKNOWN
        aligned = lambda xs: xs[0] if len(xs) == len(names) else ""   # noqa: E731
        lead = (names[0], aligned(sorts), aligned(ids), aligned(dg))
    else:
        lead = (names[0] if names else credit, sorts[0] if len(sorts) == 1 else _first(t, "albumartistsort"),
                ids[0] if len(ids) == 1 else "", dg[0] if len(dg) == 1 else "")
    to, keep = mapped(lead[0])
    if keep:
        return lead if changed(lead[0]) else None
    if to:
        return _found(to, [lead[2]] if lead[2] else [], members_of)
    if c.get("bands", True):
        # (MusicBrainz first; Discogs when MusicBrainz names no such member or has no ID for the
        # band. Unknown - the credit kept as the files hold it - only when no database that
        # was asked could answer: MusicBrainz's answer stands when Discogs cannot be reached)
        def ask_both(mbid, dgid):
            hit, unknown = None, {}
            for which, some_id, ask in (("mb", mbid, members_of), ("dg", dgid, discogs_members_of)):
                if hit or not some_id or not ask:
                    continue
                members = ask(some_id)
                unknown[which] = members is None
                hit = leader_of(lead[0], members) if members else None
            return hit, unknown
        hit, unknown = ask_both(lead[2], lead[3])
        if not hit and find_ids and not (unknown.get("mb") or unknown.get("dg")) \
                and len(_no_the(fold(lead[0])).split()) >= 2:      # (a member's name and more)
            # (no leader by the credit's own IDs, or none: the band's other database, or the band
            # found by its name; a leader found there stands, nothing found keeps the credit)
            found = find_ids(lead[0], lead[2]) or ("", "")
            more = (found[0] if found[0] and found[0] != lead[2] else "",
                    found[1] if found[1] and found[1] != lead[3] else "")
            if any(more):
                hit, _more_unknown = ask_both(*more)
        # (MusicBrainz not reached, or the band known only to Discogs and it not reached)
        unknown = unknown.get("mb") or ("mb" not in unknown and unknown.get("dg"))
        if hit:
            lead = (hit[0], hit[1] or "", hit[2] or "", hit[3] if len(hit) > 3 else "")
        elif unknown:
            return UNKNOWN
    return lead if changed(lead[0]) else None


# NAM-8: the join phrases that credit a lead with a guest or an accompanying act ("Robin Trower
# featuring Sari Schorr", "Ella Fitzgerald with Count Basie Orchestra", "X presents Y"): the
# first artist is the album artist whatever the member lists say. "&", "and", ",", "/", "x",
# "vs" join equals.
_LEAD_JOIN = re.compile(r"(?<![^\W\d_])(?:feat\.?|featuring|ft\.?|with|w/|presents|pres\.|introducing)"
                        r"(?![^\W\d_])", re.I)


def joins(credit, names):
    """The join phrases between NAMES as the credit text spells them ([] for one name; None
    when the names cannot be found in order in the text, e.g. a credit written one value per
    artist)."""
    low, pos, out = str(credit or "").casefold(), 0, []
    for k, n in enumerate(names):
        n = str(n or "").casefold()
        i = low.find(n, pos) if n else -1
        if i < 0:
            return None
        if k:
            out.append(str(credit)[pos:i])
        pos = i + len(n)
    return out


# NAM-1b: the join a credit puts between a band and its line-up ("Bill Bruford's Earthworks -
# Django Bates, Iain Ballamy, Bill Bruford, Mick Hutton"; Discogs writes an en dash)
_LINEUP_JOIN = re.compile(r"^\s+[-\u2013\u2014]\s+$")


def band_then_lineup(credit, names, ids=(), dg=(), members_of=None, discogs_members_of=None) -> bool:
    """NAM-1b: a credit naming a band and then, after " - ", its line-up for this record: every
    other name joined by commas or "&"/"and", and - where MusicBrainz (else Discogs) lists the
    band's members - at least one of them a member. The band is the album artist, never its first
    member nor the whole line-up."""
    js = joins(credit, names) if credit and len(names) >= 3 else None
    if not js or not _LINEUP_JOIN.match(js[0]):
        return False
    if any(_LEAD_JOIN.search(j) or not re.fullmatch(r"\s*(?:,|&|and)\s*", j, re.I) for j in js[1:]):
        return False
    for some_id, ask in ((ids[0] if len(ids) == len(names) else "", members_of),
                         (dg[0] if len(dg) == len(names) else "", discogs_members_of)):
        if not some_id or not ask:
            continue
        members = ask(some_id)
        if members:                           # (the database lists the band's members: one is credited)
            listed = {fold(m[0]) for m in members}
            return any(fold(n) in listed for n in names[1:])
        if members is not None:
            return False                      # (the first name is no band with members)
    return True


def lead_credit(credit, names) -> bool:
    """NAM-8: a credit whose first artist is joined to the rest by a lead phrase ("feat.",
    "featuring", "ft.", "with", "presents", "introducing")."""
    js = joins(credit, names) if credit and len(names) >= 2 else None
    return bool(js) and bool(_LEAD_JOIN.search(js[0]))


def guest_after_partners(credit, names) -> bool:
    """NAM-8: equal partners before a guest ("Pat Metheny & Lyle Mays with Nana Vasconcelos"):
    a lead join after the first. The whole credit is kept - never cut to the first partner."""
    js = joins(credit, names) if credit and len(names) >= 3 else None
    return bool(js) and not _LEAD_JOIN.search(js[0]) and any(_LEAD_JOIN.search(j) for j in js[1:])


# NAM-8: joins that never make persons a lead and partners: MusicBrainz's "; " (a classical
# credit: "Johann Sebastian Bach; Glenn Gould" - the composer first) and " / " (a split release)
_NOT_PARTNERS = (";", "/")
_PERFORMS = ("performer", "conductor")


def persons_as_equals(credit, names) -> bool:
    """NAM-8: the credit's joins as written allow the person rule: all found, none a ";" or "/"
    (never when the joins cannot be read)."""
    js = joins(credit, names) if credit and len(names) >= 2 else None
    return js is not None and not any(c in j for j in js for c in _NOT_PARTNERS)


def classical(tracks, names, ids, profile=None) -> bool:
    """NAM-8: a classical release - the profile's tradition is western classical, a track's genre
    is a classical one, or a credited artist is the composer of the works and performs on none of
    them (MusicBrainz's composer and performer relationships: "Ludwig van Beethoven; Martha
    Argerich"). With no performer credits at all, a credited composer is enough."""
    tradition = profile.get("tradition") if hasattr(profile, "get") else ""
    if str(tradition or "") == "western_classical":
        return True
    composers, composer_ids, performers = set(), set(), set()
    _cls = compilations  # (vendored: genre_kind is in tm_album_artist_deps)
    for t in tracks or ():
        if _first(t, "~classical") or any(_cls.genre_kind(g) == "strong" for g in _list(t, "genre")):
            return True             # (CLS-2's genres: never "Neo-Classical", "Symphonic Metal")
        composers |= {fold(x) for x in _list(t, "composer")}
        composer_ids |= set(_list(t, "musicbrainz_composerid"))
        for k in t:
            if str(k).split(":")[0] in _PERFORMS:
                performers |= {fold(x) for x in _list(t, k)}
    for k, n in enumerate(names):
        mine = fold(n) in composers or (len(ids) == len(names) and str(ids[k]) in composer_ids)
        if mine and fold(n) not in performers:
            return True
    return False


class Members(list):
    """A database's answer for one artist: its members, and kind - "person", "group" or ""
    (the database did not say)."""
    kind = ""

    def __init__(self, items=(), kind=""):
        super().__init__(items)
        self.kind = kind


def _kind(got) -> str:
    return getattr(got, "kind", "") or ""


def _answer(mbid, dgid, members_of, discogs_members_of):
    """One artist's answer from MusicBrainz, else Discogs: ("members", list) when members are
    known; ("person", []) a person; ("group", []) a group neither lists members for; ("none",
    []) no database answered; ("down", []) none answered and one could not be reached. A
    definitive answer stands though the other database is unreachable (NAM-8)."""
    state, down = "none", False
    for some_id, ask in ((mbid, members_of), (dgid, discogs_members_of)):
        if not some_id or not ask:
            continue
        got = ask(some_id)
        if got is None:
            down = True                                  # (unreachable: maybe the other knows)
            continue
        if isinstance(got, tuple) and not got:
            continue                                     # (NOT_ASKED / not known: no answer)
        if got:
            return "members", list(got)
        kind = _kind(got)
        if kind == "group":
            state = "group"                              # (no members here: maybe the other)
        elif state != "group":
            # (an empty list: a person - MusicBrainz's type says so, or a stand-in that says nothing)
            return ("person", []) if kind in ("person", "") else ("none", [])
    if state == "group":
        return "group", []
    return ("down", []) if down else ("none", [])


def _equals(names, ids, dg, members_of=None, discogs_members_of=None, persons=True):
    """NAM-8: a joint credit is a collaboration of equals (True: Calexico and Iron & Wine, two
    bands) unless its first artist is a member of another act it names - a leader credited with
    their own band (False: Thomas Strønen & Time Is A Blind Guide, Strønen in the band) - or a
    person credited with a group no database lists members for (False: the person leads, as
    before NAM-8) - or every artist it names is a person by MusicBrainz's type (False: Paolo
    Fresu & Omar Sosa is filed under Paolo Fresu; PERSONS False - a ";" or "/" join, a classical
    release - leaves that last case out). The other acts' members come from
    MusicBrainz (its "member of band" relationships), else from Discogs. None when no database
    answered for any of them (no IDs: the first artist leads, as before); "unknown" when the
    answer depends on an artist no database could be reached for."""
    lead = fold(names[0])
    same = len(ids) == len(names), len(dg) == len(names)
    # (and by its IDs: a name credited otherwise on the sleeve, Discogs's "L. Person" for "Lead Person")
    lead_ids = {str(x) for x in ((ids[0] if same[0] else ""), (dg[0] if same[1] else ""))} - {""}
    answers = [_answer(ids[k] if same[0] else "", dg[k] if same[1] else "", members_of, discogs_members_of)
               for k in range(1, len(names))]
    for state, members in answers:
        if state == "members" and any(fold(m[0]) == lead or (lead_ids & {str(x) for x in m[2:4] if x})
                                      for m in members):
            return False                                 # (the first artist leads this band)
    if any(state == "group" for state, _m in answers):
        # (a group without member data: led by the first artist when that one is a person)
        first = _answer(ids[0] if same[0] else "", dg[0] if same[1] else "", members_of, discogs_members_of)
        if first[0] == "person":
            return False
        if first[0] == "down":
            return "unknown"
    if any(state == "down" for state, _m in answers):
        return "unknown"
    if persons and same[0] and members_of and not any(st in ("members", "group") for st, _m in answers) \
            and all(_mb_person(ids[k], members_of) for k in range(1, len(names))):
        # (NAM-8, decided 2026-11-17: persons alone, joined as equals - "Yelena Eckemoff, Arild
        # Andersen, Thomas Strønen" - are filed under the first-credited; only MusicBrainz's type
        # "Person" counts, a Discogs artist without members proves nothing. The others' answers
        # are already in hand; the first artist is asked only when they are all persons)
        first = members_of(ids[0]) if ids[0] else NOT_ASKED
        if first is None:
            return "unknown"         # (MusicBrainz unreachable: the files' album artist stays)
        if _kind(first) == "person":
            return False
    return True if any(state != "none" for state, _m in answers) else None


def _mb_person(mbid, members_of) -> bool:
    """NAM-8: MusicBrainz's type for the artist MBID is Person (never assumed without it)."""
    return bool(mbid and members_of) and _kind(members_of(mbid)) == "person"


def _found(name, ids, members_of):
    """Your own album artist NAME, with its sort name and ID when the credited band lists a
    member of that name."""
    if len(ids) == 1 and members_of:
        for m in members_of(ids[0]) or ():
            if fold(m[0]) == fold(name):
                return (name, m[1] or "", m[2] or "", "")
    return (name, "", "", "")


def apply(targets: list, profile, members_of=None, discogs_members_of=None, find_ids=None) -> list:
    """Every track's tags with the album artist chosen (choose, from the first track's: the
    album artist is the album's)."""
    if not targets or not enabled(profile):
        return targets
    lead = choose(targets[0], profile, members_of, discogs_members_of, find_ids, targets)
    if lead == UNKNOWN:
        keys = ("albumartist", "albumartists", "albumartistsort", "musicbrainz_albumartistid",
                "discogs_albumartist_id", "~albumartists", "~albumartists_sort")
        return [{k: v for k, v in t.items() if k not in keys} for t in targets]
    if not lead:
        return targets
    name, sort, mbid, dgid = lead
    out = []
    for t in targets:
        t = dict(t)
        t.pop("~discogs_albumartist_id", None)          # (the whole credit's: not the lead's)
        t.pop("~discogs_albumartists", None)
        remove = [str(x) for x in t.get("~remove") or []]
        t["albumartist"] = t["albumartists"] = t["~albumartists"] = [name]
        for key, value in (("albumartistsort", sort), ("musicbrainz_albumartistid", mbid),
                           ("discogs_albumartist_id", dgid)):
            if value:
                t[key] = [value]
            elif key in t or key != "discogs_albumartist_id":
                t.pop(key, None)                         # (unknown: never the whole credit's)
                if key not in remove:
                    remove.append(key)
        if sort:
            t["~albumartists_sort"] = [sort]
        else:
            t.pop("~albumartists_sort", None)
        if remove:
            t["~remove"] = remove
        out.append(t)
    return out


MB_ARTIST = "https://musicbrainz.org/ws/2/artist/{0}?inc=artist-rels+url-rels&fmt=json"


def linked_discogs(http, mbid, log=None) -> str:
    """The Discogs artist ID MusicBrainz's entry for MBID links to ("" when none or not read)."""
    try:
        det = http.get_json(MB_ARTIST.format(mbid), "mb")
    except Exception as exc:
        if log:
            log.info("album artist: links of %s not read: %s", mbid, exc)
        return ""
    for r in (det or {}).get("relations") or [] if isinstance(det, dict) else []:
        m = re.search(r"discogs\.com/artist/(\d+)", str((r.get("url") or {}).get("resource") or ""))
        if r.get("type") == "discogs" and m:
            return m.group(1)
    return ""


def artist_named(http, name, log=None) -> str:
    """The MusicBrainz ID of the one artist named exactly NAME (case, accents and "&"/"and"
    aside); "" when there is none, several, or MusicBrainz could not be asked."""
    import urllib.parse
    q = urllib.parse.quote(f'artist:"{name}"')
    try:
        res = http.get_json(f"https://musicbrainz.org/ws/2/artist?query={q}&limit=10&fmt=json", "mb")
    except Exception as exc:
        if log:
            log.info("album artist: %s not searched: %s", name, exc)
        return ""
    same = [a.get("id") for a in (res or {}).get("artists") or [] if isinstance(res, dict)
            and fold(a.get("name")) == fold(name) and a.get("id")]
    return same[0] if len(set(same)) == 1 else ""


def band_members(http, mbid, log=None):
    """[(name, sort name, MusicBrainz ID)] of the people MusicBrainz lists as members of the
    artist MBID (none for a person); None when MusicBrainz could not be asked (the album artist
    is then left as credited)."""
    try:
        det = http.get_json(MB_ARTIST.format(mbid), "mb")     # (one request: linked_discogs reads it too)
    except Exception as exc:                             # (an outage: the credit stays)
        if log:
            log.info("album artist: members of %s not read: %s", mbid, exc)
        return None
    if not isinstance(det, dict):
        return NOT_ASKED               # (no such artist, a 404: not known - never "a person")
    kind = {"person": "person", "group": "group", "orchestra": "group", "choir": "group"}.get(
        str(det.get("type") or "").casefold(), "")
    if kind == "person":
        return Members((), "person")
    out = Members((), kind)
    for r in det.get("relations") or []:
        a = r.get("artist") or {}
        if r.get("type") == "member of band" and r.get("direction") == "backward" and a.get("name"):
            out.append((a["name"], a.get("sort-name") or "", a.get("id") or ""))
    return out


def discogs_members(http, dgid, log=None):
    """[(name, "", "", Discogs ID)] of the members Discogs lists for its artist DGID (none for a
    person or a band without them; Discogs' "(2)" name suffix dropped); None when Discogs could
    not be asked."""
    try:
        det = http.get_json(f"https://api.discogs.com/artists/{int(dgid)}", "discogs")
    except (TypeError, ValueError):
        return []
    except Exception as exc:                             # (an outage or no key: the credit stays)
        if log:
            log.info("album artist: Discogs members of %s not read: %s", dgid, exc)
        return None
    out = []
    for m in (det or {}).get("members") or [] if isinstance(det, dict) else []:
        name = re.sub(r"\s*\(\d+\)$", "", str(m.get("name") or "")).strip()
        if name:
            out.append((name, "", "", str(m.get("id") or "")))
    return Members(out, "group" if out else "")
